test('Both includes text and interword spaces (v2 regression)',()=>assert.deepEqual(indices(api.collectUnits(data('a b c'),s({target:'both'}))),[0,1,2,3,4]));
test('Letters tracking omits outgoing glyphs and preserves actual word-gap boundaries',()=>assert.deepEqual(indices(api.collectUnits(data('abc def'),s())),[0,1,4,5,6]));
test('Letters on nontracking properties still includes every letter',()=>assert.deepEqual(indices(api.collectUnits(data('abc def'),s({property:'pointSize'}))),[0,1,2,4,5,6]));
test('Spaces mode preserves every letter and groups adjacent gaps',()=>assert.deepEqual(indices(api.collectUnits(data('a  b c'),s({target:'spaces'}))),[1,2,4]));
test('Both character mode counts letters and individual spaces in order',()=>assert.deepEqual(indices(api.collectUnits(data('a  b c'),s({target:'both',mode:'character'}))),[0,1,2,3,4,5]));
test('Both line mode includes internal spaces but excludes line-ending spaces',()=>{const d=data('abc def ghi');d.lines=[{start:0,end:7},{start:8,end:10}];const u=api.collectUnits(d,s({mode:'line',target:'both'}));assert.deepEqual(indices([u[0]]),[0,1,2,3,4,5,6]);});
