test('tracking letters still preserve outgoing gaps when restarting per word',()=>{const p=api.makePlan(data('abcd xy'),s({mode:'character',restart:'word'}));assert.deepEqual(plain(p.distribution.values),[0,50,100,0,100]);assert.deepEqual(indices(p.units),[0,1,2,5,6]);});
test('words restart a complete ramp in each sentence',()=>{const p=api.makePlan(data('one two three. four five six.'),s({restart:'sentence'}));assert.equal(p.groups.length,2);assert.deepEqual(plain(p.distribution.values),[0,50,100,0,50,100]);});
test('sentence units restart per paragraph with independent sample counts',()=>{const p=api.makePlan(data('One. Two!\rThree? Four. Five.'),s({mode:'sentence',restart:'paragraph'}));assert.deepEqual(Array.from(p.groups,g=>g.count),[2,3]);assert.deepEqual(plain(p.distribution.values),[0,100,0,50,100]);});
test('paragraph units skip empty paragraphs without losing scope bounds',()=>{const p=api.makePlan(data('alpha beta\r\rdelta epsilon\rfinal'),s({mode:'paragraph'}));assert.equal(p.units.length,3);assert.deepEqual(plain(p.distribution.values),[0,50,100]);assert.equal(new Set(indices(p.units)).size,indices(p.units).length);});
test('sentence recognition handles decimals, initials, abbreviations, quotes and Unicode terminals',()=>{const p=api.makePlan(data('Dr. A. Smith paid 3.14. “Done!” Next? 你好。 再见！'),s({mode:'sentence'}));assert.equal(p.units.length,5);});
test('sentence recognition treats paragraph breaks as sentence boundaries',()=>{const p=api.makePlan(data('No punctuation\rStill a sentence'),s({mode:'sentence'}));assert.equal(p.units.length,2);});
test('frame units distribute over visible linked frames and exclude overset',()=>{const d=data('alpha beta gamma delta extra');d.frames=[{start:0,end:10,id:8},{start:11,end:21,id:9}];const p=api.makePlan(d,s({mode:'frame',target:'both'}));assert.equal(p.units.length,2);assert.deepEqual(plain(p.distribution.values),[0,100]);assert.ok(indices(p.units).every(x=>x<=21));});
test('word curves restart per frame and omit the uncomposed tail',()=>{const d=data('aa bb cc dd ee');d.frames=[{start:0,end:5,id:8},{start:6,end:11,id:9}];const p=api.makePlan(d,s({restart:'frame',target:'both'}));assert.deepEqual(plain(p.distribution.values),[0,100,0,100]);assert.ok(indices(p.units).every(x=>x<12));});
test('units crossing resulting-line groups split at the boundary without double application',()=>{const d=data('abcdefgh ij kl');d.lines=[{start:0,end:3},{start:4,end:8},{start:9,end:13}];const p=api.makePlan(d,s({restart:'line',target:'both',property:'pointSize',min:10,max:30}));assert.deepEqual(Array.from(p.groups,g=>g.count),[1,1,2]);assert.deepEqual(plain(p.distribution.values),[10,10,10,30]);const all=indices(p.units);assert.equal(new Set(all).size,all.length);assert.ok(!all.includes(8),'Exclude the trailing space at a line edge');});
test('step limits and bell sampling are calculated independently for every group',()=>{const p=api.makePlan(data('aa bbbbb ccccccc'),s({mode:'character',restart:'word',property:'pointSize',curve:'gaussian',steps:5,min:10,max:30}));assert.deepEqual(Array.from(p.groups,g=>g.distribution.steps),[2,5,5]);assert.deepEqual(plain(p.groups[0].distribution.values),[10,10]);assert.equal(Math.max(...p.groups[1].distribution.values),30);assert.equal(Math.max(...p.groups[2].distribution.values),30);});
test('frame ownership is part of the adaptive composition key',()=>{const d=data('alpha beta');d.frames=[{start:0,end:9,id:8}];const a=api.geometryKey(d);d.frames=[{start:0,end:4,id:8},{start:5,end:9,id:9}];assert.notEqual(api.geometryKey(d),a);});
test('character per resulting line recomposes and reaches a consistent final grouping',()=>{const h=host('alpha beta gamma delta'),all=h.chars;let changed=false;h.story.recompose=()=>{if(h.chars.some(c=>c.tracking>0)){changed=true;h.frame.lines=collection([{characters:collection(all.slice(0,6))},{characters:collection(all.slice(6,11))},{characters:collection(all.slice(11))}]);}};const p=new api.PreviewSession(h.target),result=p.preview(s({mode:'character',restart:'line',target:'both'}));assert.ok(changed);assert.ok(result.passes>=2);assert.equal(result.groups.length,3);const actual=api.makePlan(api.capture(h.story,result.data.bounds),result.settings);assert.deepEqual(plain(actual.distribution.values),plain(result.distribution.values));for(let i=0;i<result.units.length;i++)for(const at of indices([result.units[i]]))assert.equal(h.chars[at].tracking,result.distribution.values[i]);p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('reapplying a grouped effect restores targets from the previous grouping',()=>{const h=host('alpha beta gamma delta');new api.PreviewSession(h.target).commit(s({mode:'character',restart:'word',target:'both',min:20,max:100}));const p=new api.PreviewSession(h.target);p.preview(s({mode:'word',restart:'never',target:'letters',max:10}));assert.equal(h.chars[4].tracking,0);assert.equal(h.chars[5].tracking,0);p.rollback();assert.ok(h.chars.some(c=>c.tracking===100));});

test('all unit/group/target combinations stay disjoint and within the chosen scope',()=>{const d=data('Alpha beta. Gamma delta!\rEpsilon zeta eta. Theta?');d.frames=[{start:0,end:24,id:8},{start:25,end:d.bounds.end-5,id:9}];d.lines=[{start:0,end:11},{start:12,end:24},{start:25,end:41},{start:42,end:d.bounds.end}];for(const mode of ['character','word','sentence','paragraph','line','frame'])for(const restart of ['never','word','sentence','paragraph','line','frame'])for(const target of ['letters','spaces','both']){let p;try{p=api.makePlan(d,s({mode,restart,target,property:'pointSize',min:10,max:30}));}catch(e){assert.match(e.message,/No matching targets/);continue;}const all=indices(p.units);assert.equal(new Set(all).size,all.length,mode+'/'+restart+'/'+target);assert.ok(all.every(i=>i>=0&&i<=d.bounds.end));assert.equal(p.units.length,p.distribution.values.length);assert.equal(p.groups.reduce((n,g)=>n+g.count,0),p.units.length);assert.ok(p.distribution.values.every(v=>Number.isFinite(v)&&v>=10&&v<=30));if(target==='spaces')assert.ok(all.every(i=>d.characters[i].kind==='space'));if(target==='letters')assert.ok(all.every(i=>d.characters[i].kind==='text'));}});
test('grouping respects absolute indices in a partial selection',()=>{const d=data('cde fghi. jkl mno');const offset=37;d.bounds.start+=offset;d.bounds.end+=offset;for(const c of d.characters)c.index+=offset;for(const key of ['words','lines'])for(const span of d[key]){span.start+=offset;span.end+=offset;}const p=api.makePlan(d,s({mode:'character',restart:'sentence',property:'pointSize',min:10,max:30}));assert.equal(p.groups.length,2);assert.ok(indices(p.units).every(i=>i>=37&&i<=d.bounds.end));assert.equal(p.groups[0].distribution.values[0],10);assert.equal(p.groups[1].distribution.values[0],10);});
test('the UI persists restart choice and group inspection never changes the document transaction',()=>{const h=uiHost();interaction=root=>{const mode=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Word'),restart=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Never — entire scope');mode.selection=2;mode.onChange();restart.selection=1;restart.onChange();const labelIndex=root.controls.findIndex(c=>c.type==='statictext'&&c.text==='Preview group'),group=root.controls[labelIndex+1];assert.equal(group.enabled,true);const transaction=h.doc.history[0],before=JSON.stringify(h.doc.state);group.text='2';group.onChanging();assert.equal(h.doc.history[0],transaction);assert.equal(JSON.stringify(h.doc.state),before);root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};const result=api.showDialog(h.target);assert.equal(result.settings.restart,'word');assert.equal(result.settings.mode,'character');assert.equal(h.doc.history.length,1);});
test('native smart-quote enumerators retain punctuation for sentence boundaries and targeting',()=>{ctx.SpecialCharacters.DOUBLE_LEFT_QUOTE=101;ctx.SpecialCharacters.DOUBLE_RIGHT_QUOTE=102;const h=host('"Done!" Next?'),first=h.chars[0],last=h.chars[6];first.contents=101;last.contents=102;const captured=api.capture(h.story,{start:0,end:h.chars.length-1}),p=api.makePlan(captured,s({mode:'sentence',property:'pointSize'}));assert.equal(captured.characters[0].text,'“');assert.equal(captured.characters[6].text,'”');assert.equal(p.units.length,2);assert.ok(indices(p.units).includes(0));});
test('width-only processing never clears tracking through an inactive text checkbox',()=>{const h=host('alpha beta');h.chars.forEach(c=>c.tracking=180);const p=new api.PreviewSession(h.target);p.preview(s({textEnabled:false,clearTracking:true}));assert.ok(h.chars.every(c=>c.tracking===180));p.rollback();assert.ok(h.chars.every(c=>c.tracking===180));});
test('frame scope resamples word values after text becomes overset and restores dropped targets',()=>{const h=host('alpha beta gamma'),all=h.chars;h.target.scopes=[{kind:'frame',bounds:{start:0,end:all.length-1}}];h.story.recompose=()=>{if(h.chars.some(c=>c.tracking>0))h.frame.lines=collection([{characters:collection(all.slice(0,11))}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'word',restart:'never'}));assert.equal(r.units.length,2);assert.equal(r.data.bounds.end,10);assert.deepEqual(plain(r.distribution.values),[0,100]);assert.ok(h.chars.slice(11).every(c=>c.tracking===0),'Dropped text must not retain a previous pass');p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('frame scope includes text newly pulled into the frame by composition',()=>{const h=host('alpha beta gamma'),all=h.chars;h.frame.lines=collection([{characters:collection(all.slice(0,11))}]);h.target.scopes=[{kind:'frame',bounds:{start:0,end:10}}];h.story.recompose=()=>{if(h.chars.some(c=>c.tracking>0))h.frame.lines=collection([{characters:collection(all)}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'word',restart:'never'}));assert.equal(r.units.length,3);assert.equal(r.data.bounds.end,all.length-1);assert.deepEqual(plain(r.distribution.values),[0,50,100]);assert.equal(h.chars.at(-1).tracking,100);p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('line cycles identify the moving boundary instead of keeping an approximate curve',()=>{let state=0;const base=data('abc def ghi'),layouts=[[{start:0,end:7},{start:8,end:10}],[{start:0,end:3},{start:4,end:10}]];assert.throws(()=>api.settleLines({capture(){return{...base,lines:layouts[state]};},restore(){},apply(){state=1-state;},recompose(){}},s({mode:'line',target:'both'})),/oscillates.*Line 1.*(?:1 and 2|2 and 1) words/);});
test('metrics fit the glyph gap below each source line rather than the midpoint between baselines',()=>{const lines=[{key:'a',column:0,baseline:20,top:6,bottom:24,leading:24},{key:'b',column:0,baseline:44,top:30,bottom:48,leading:24}];const positions=api.metricsRows(lines,3.6,1.4,.5);assert.ok(positions.a.baseline-3.6>=24.5-1e-9);assert.ok(positions.a.baseline+1.4<=29.5+1e-9);assert.equal(positions.a.crowded,false);assert.ok(positions.b.baseline-3.6>48);});
test('metrics flag insufficient leading and keep independent columns separate',()=>{const positions=api.metricsRows([{key:'a',column:0,baseline:20,top:6,bottom:24,leading:16},{key:'b',column:0,baseline:36,top:22,bottom:40,leading:16},{key:'c',column:1,baseline:20,top:6,bottom:24,leading:30},{key:'d',column:1,baseline:50,top:36,bottom:54,leading:30}],3.6,1.4,.5);assert.equal(positions.a.crowded,true);assert.equal(positions.c.crowded,false);assert.ok(positions.c.baseline-3.6>=24.5);assert.ok(positions.c.baseline+1.4<=35.5);});
test('line convergence checks effective tracking values rather than requiring identical line counts',()=>{let state=0,last;const base=data('abc def ghi'),layouts=[[{start:0,end:7},{start:8,end:10}],[{start:0,end:3},{start:4,end:7},{start:8,end:10}]],cfg=s({mode:'word',restart:'line',target:'letters',min:150,max:150});const baseline=Object.fromEntries(base.characters.map(c=>[c.index,0]));const p=api.settleLines({capture(){return{...base,lines:layouts[state]};},restore(){},apply(p){last=p;state=1-state;},matches(applied,desired){return api.trackingPlansEquivalent(applied,desired,baseline);},recompose(){}},cfg);assert.equal(p.passes,1);assert.equal(p.groups.length,3);assert.equal(api.trackingPlansEquivalent(last,p,baseline),true);});
test('effective-tracking convergence rejects changed values and dropped nonbaseline targets',()=>{const make=(start,end,value)=>({units:[{spans:[{start,end}]}],distribution:{values:[value]}});assert.equal(api.trackingPlansEquivalent(make(0,2,150),make(0,1,150),{0:0,1:0,2:0}),false);assert.equal(api.trackingPlansEquivalent(make(0,2,150),make(0,2,100),{0:0,1:0,2:0}),false);assert.equal(api.trackingPlansEquivalent(make(0,2,0),make(0,1,0),{0:0,1:0,2:0}),true);});
test('clear tracking follows incoming frame text and preserves the original overset baseline',()=>{const h=host('alpha beta gamma delta epsilon'),all=h.chars;h.chars.forEach(c=>c.tracking=180);h.frame.lines=collection([{characters:collection(all.slice(0,11))}]);h.target.scopes=[{kind:'frame',bounds:{start:0,end:10}}];h.story.recompose=()=>{if(h.chars[0].tracking===0)h.frame.lines=collection([{characters:collection(all.slice(0,17))}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({clearTracking:true,max:100}));assert.equal(r.data.bounds.end,16);assert.equal(h.chars[15].tracking,0);assert.equal(h.chars[16].tracking,0);assert.ok(h.chars.slice(17).every(c=>c.tracking===180));p.rollback();assert.ok(h.chars.every(c=>c.tracking===180));});
test('clear tracking restores the original baseline when previously visible text becomes overset',()=>{const h=host('alpha beta gamma'),all=h.chars;h.chars.forEach(c=>c.tracking=180);h.target.scopes=[{kind:'frame',bounds:{start:0,end:all.length-1}}];h.story.recompose=()=>{h.frame.lines=collection([{characters:collection(h.chars[6].tracking>180?all.slice(0,11):all)}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({clearTracking:true,min:200,max:500}));assert.equal(r.data.bounds.end,10);assert.ok(h.chars.slice(11).every(c=>c.tracking===180));p.rollback();assert.ok(h.chars.every(c=>c.tracking===180));});
test('committed frame clearing saves zero for incoming gaps on later replacement runs',()=>{const h=host('alpha beta gamma delta epsilon'),all=h.chars;h.chars.forEach(c=>c.tracking=180);h.frame.lines=collection([{characters:collection(all.slice(0,11))}]);h.target.scopes=[{kind:'frame',bounds:{start:0,end:10}}];h.story.recompose=()=>{if(h.chars[0].tracking===0)h.frame.lines=collection([{characters:collection(all.slice(0,17))}]);};new api.PreviewSession(h.target).commit(s({clearTracking:true,max:100}));new api.PreviewSession(h.target).commit(s({clearTracking:false,max:20}));assert.equal(h.chars[15].tracking,0);assert.equal(h.chars[16].tracking,0);assert.ok(h.chars.slice(17).every(c=>c.tracking===180));h.doc.undo();h.doc.undo();assert.ok(h.chars.every(c=>c.tracking===180));});
test('managed line-break insertion and removal preserve sparse formatting histories',()=>{const rows=[{start:0,end:4,values:{tracking:10}},{start:5,end:9,values:{tracking:40}}],offsets=[2,5,8],positions=[2,6,10];const inserted=plain(api.remapSnapshot(rows,offsets,false));const removed=plain(api.remapSnapshot(inserted,positions,true));function expand(rows){const v={};for(const row of rows)for(let i=row.start;i<=row.end;i++)v[i]=row.values.tracking;return v;}assert.deepEqual(expand(removed),expand(rows));assert.ok(positions.every(p=>!Object.hasOwn(expand(inserted),p)));assert.deepEqual(plain(api.remapBounds({start:3,end:8},offsets,false)),{start:4,end:11});assert.deepEqual(plain(api.remapBounds({start:4,end:11},positions,true)),{start:3,end:8});});
test('line-break removal excludes owned break characters from saved values',()=>{const rows=[{start:0,end:7,values:{tracking:0}}],r=plain(api.remapSnapshot(rows,[0,3,7],true));const all=[];for(const row of r)for(let i=row.start;i<=row.end;i++)all.push(i);assert.deepEqual(all,[0,1,2,3,4]);});
test('width-only processing preserves existing fixed line breaks and their ownership',()=>{const h=host('alpha\nbeta'),key='TrackingRamp.v5.lineBreaks',meta=JSON.stringify({version:1,property:'tracking',signature:api.signature(h.story),positions:[5]});h.story.insertLabel(key,meta);const p=new api.PreviewSession(h.target);p.preview(s({textEnabled:false}));assert.equal(h.story.contents,'alpha\nbeta');assert.equal(h.story.extractLabel(key),meta);p.rollback();assert.equal(h.story.extractLabel(key),meta);});

test('underline properties enable targets and preserve automatic values and flags on Cancel',()=>{for(const property of ['underlineWeight','underlineOffset']){const h=host('alpha beta gamma'),before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target),r=p.preview(s({property,min:.25,max:4}));assert.equal(h.chars[0][property],.25);assert.equal(h.chars.at(-1)[property],4);assert.ok(h.chars[0].underline);assert.equal(h.chars[5].underline,false);p.rollback();assert.equal(JSON.stringify(h.doc.state),before);}});
test('reapplication restores underline activation and automatic defaults outside the new targets',()=>{const h=host('alpha beta gamma');new api.PreviewSession(h.target).commit(s({property:'underlineWeight',target:'both',min:.5,max:3}));new api.PreviewSession(h.target).commit(s({property:'underlineWeight',target:'letters',min:.25,max:1}));assert.equal(h.chars[5].underline,false);assert.equal(h.chars[5].underlineWeight,-9999);assert.equal(h.chars[0].underline,true);assert.equal(h.chars.at(-1).underlineWeight,1);});
test('replacing underline weight keeps activation owned by an offset effect',()=>{const h=host('alpha beta gamma');new api.PreviewSession(h.target).commit(s({property:'underlineWeight',target:'both',min:.5,max:3}));new api.PreviewSession(h.target).commit(s({property:'underlineOffset',target:'both',min:1,max:5}));new api.PreviewSession(h.target).commit(s({property:'underlineWeight',target:'letters',min:.25,max:1}));assert.equal(h.chars[5].underline,true);assert.ok(h.chars[5].underlineOffset>0);});
test('paragraph indents are atomic even when a requested restart crosses a paragraph',()=>{const d=data('one two\rthree four\rfive six'),r=api.makePlan(d,s({property:'leftIndent',mode:'character',restart:'word',target:'spaces',min:0,max:24}));assert.equal(r.units.length,3);assert.equal(r.settings.mode,'paragraph');assert.equal(r.settings.restart,'never');assert.equal(r.settings.target,'both');assert.deepEqual(Array.from(r.distribution.values),[0,12,24]);assert.deepEqual(plain(r.units[0].spans),[{start:0,end:7}]);});
test('indent selection affects complete intersecting paragraphs and restores those paragraphs on reapply',()=>{for(const property of ['leftIndent','rightIndent','firstLineIndent']){const h=host('outside\rfirst selected paragraph\rsecond selected paragraph\runtouched');h.target.scopes=[{kind:'selection',bounds:{start:11,end:38}}];const before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target),r=p.preview(s({property,min:6,max:24}));assert.equal(r.units.length,2);assert.ok(h.chars.slice(8,33).every(c=>c[property]===6));assert.ok(h.chars.slice(33,59).every(c=>c[property]===24));assert.equal(h.chars[0][property],0);assert.equal(h.chars.at(-1)[property],0);p.rollback();assert.equal(JSON.stringify(h.doc.state),before);new api.PreviewSession(h.target).commit(s({property,min:6,max:24}));h.target.scopes=[{kind:'selection',bounds:{start:11,end:14}}];new api.PreviewSession(h.target).commit(s({property,min:3,max:3}));assert.equal(h.chars[8][property],3);assert.equal(h.chars[33][property],0);h.doc.undo();h.doc.undo();assert.equal(JSON.stringify(h.doc.state),before);}});
test('identical normalized indent previews reuse the same transaction',()=>{const h=host('one\rtwo\rthree'),p=new api.PreviewSession(h.target),cfg=s({property:'leftIndent',min:0,max:20}),first=p.preview(cfg),transaction=h.doc.history[0];assert.equal(p.preview(cfg),first);p.commit(cfg);assert.equal(h.doc.history[0],transaction);assert.equal(h.doc.history.length,1);});
test('indent UI locks paragraph controls and restores the prior structure on another property',()=>{const h=uiHost();interaction=root=>{const property=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Tracking'),mode=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Word'),change=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Letters'),restart=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Never — entire scope');mode.selection=2;mode.onChange();property.selection=15;property.onChange();assert.equal(mode.selection.index,4);assert.equal(change.selection.index,2);assert.equal(restart.selection.index,0);assert.equal(mode.enabled,false);assert.equal(restart.enabled,false);property.selection=13;property.onChange();assert.equal(mode.selection.index,2);assert.equal(mode.enabled,true);assert.equal(change.enabled,true);root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);});
test('new properties expose point units, fractional steps, and safe signed indent limits',()=>{for(const id of ['underlineWeight','underlineOffset','leftIndent','rightIndent','firstLineIndent'])assert.equal(api.propertyInfo(id).unit,'pt');assert.equal(api.propertyInfo('leftIndent').low,0);assert.equal(api.propertyInfo('rightIndent').low,0);assert.ok(api.propertyInfo('firstLineIndent').low<0);assert.deepEqual(Array.from(api.buildDistribution(3,s({property:'underlineWeight',min:.25,max:.75})).values),[.25,.5,.75]);});
test('native plural paragraph specifiers are resolved before storing scalar story indices',()=>{const h=host('outside\rselected one\rselected two'),originalRange=h.story.characters.itemByRange;h.story.characters.itemByRange=(a,b)=>{const r=originalRange(a,b),real=r.paragraphs;r.paragraphs={...real,item(i){const p=real.item(i);return{characters:{length:p.characters.length,firstItem:()=>({index:[p.characters.firstItem().index]}),lastItem:()=>({index:[p.characters.lastItem().index]})}};}};return r;};h.target.scopes=[{kind:'selection',bounds:{start:10,end:25}}];const p=new api.PreviewSession(h.target),r=p.preview(s({property:'leftIndent',min:0,max:12}));assert.ok(r.units.every(u=>u.spans.every(span=>typeof span.start==='number'&&typeof span.end==='number')));p.rollback();});

test('automatic stabilization keeps a cycling line curve without reducing requested values',()=>{const h=host('abc def ghi'),all=h.chars,A=[{characters:collection(all.slice(0,8))},{characters:collection(all.slice(8))}],B=[{characters:collection(all.slice(0,4))},{characters:collection(all.slice(4))}];h.frame.lines=collection(A);h.story.recompose=()=>{h.frame.lines=collection(h.chars[4].tracking===0?B:A);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'line',target:'both',max:100,autoStabilize:true,lockLines:false}));assert.equal(r.fixedSampling,true);assert.deepEqual(Array.from(r.distribution.values),[0,100]);p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('automatic frame stabilization restores outgoing text without restarting the sampling cycle',()=>{const h=host('abc def ghi'),all=h.chars;h.target.scopes=[{kind:'frame',bounds:{start:0,end:10}}];h.story.recompose=()=>{h.frame.lines=collection([{characters:collection(h.chars[8].tracking>0?all.slice(0,8):all)}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({target:'both',autoStabilize:true,lockLines:false}));assert.equal(r.fixedSampling,true);assert.ok(r.units.flatMap(u=>u.spans).every(span=>span.end<=r.data.bounds.end));assert.equal(h.chars[8].tracking,0);p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('kept properties survive draft changes and Cancel restores the whole stack',()=>{const h=host('alpha beta gamma'),before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target),skew=s({property:'skew',min:-10,max:20});p.preview(skew);p.keep(skew);const values=h.chars.map(c=>c.skew);p.preview(s({max:200}));p.preview(s({max:40}));assert.deepEqual(h.chars.map(c=>c.skew),values);assert.ok(h.chars.some(c=>c.tracking>0));p.rollback();assert.equal(JSON.stringify(h.doc.state),before);});
test('committing stacked properties creates one Undo group and blocks duplicate properties',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target),skew=s({property:'skew',min:-10,max:20});p.keep(skew);assert.throws(()=>p.preview(skew),/already|kept/i);p.commit(s({max:100}));assert.equal(h.doc.history.length,1);assert.ok(h.chars.some(c=>c.skew!==0));h.doc.undo();assert.ok(h.chars.every(c=>c.skew===0&&c.tracking===0));});

test('Undo addition returns the kept settings and restores them as the editable stage',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target),skew=s({property:'skew',min:-12,max:18,curve:'sine'});p.keep(skew);p.preview(s({max:100}));const saved=p.undoAddition();assert.equal(saved.property,'skew');assert.equal(saved.curve,'sine');assert.equal(p.stages.length,0);p.preview(saved);assert.ok(h.chars.every(c=>c.tracking===0));assert.ok(h.chars.some(c=>c.skew!==0));p.rollback();});
test('kept-only preview preserves baked effects when the active preview is off',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target),skew=s({property:'skew',min:-12,max:18});p.keep(skew);p.preview(s({max:100}));p.preview(null);assert.ok(h.chars.some(c=>c.skew!==0));assert.ok(h.chars.every(c=>c.tracking===0));assert.equal(h.doc.history.length,1);p.rollback();assert.ok(h.chars.every(c=>c.skew===0));});
test('three-property stack replays frozen values and commits as one Undo action',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'skew',min:-10,max:20}));const skew=h.chars.map(c=>c.skew);p.keep(s({max:100}));const tracking=h.chars.map(c=>c.tracking);p.commit(s({property:'baselineShift',min:0,max:5}));assert.deepEqual(h.chars.map(c=>c.skew),skew);assert.deepEqual(h.chars.map(c=>c.tracking),tracking);assert.equal(h.doc.history.length,1);h.doc.undo();assert.ok(h.chars.every(c=>c.skew===0&&c.tracking===0&&c.baselineShift===0));});
test('a failed draft can return to the last kept effect without leaving draft formatting',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'skew',min:-10,max:20}));assert.throws(()=>p.preview(s({property:'designAxes',axisName:'Missing',min:100,max:900})));p.preview(null);assert.ok(h.chars.some(c=>c.skew!==0));assert.ok(h.chars.every(c=>c.tracking===0));p.rollback();});
test('strict composition mode still rejects a cycle and restores the complete baseline',()=>{const h=host('abc def ghi'),all=h.chars,A=[{characters:collection(all.slice(0,8))},{characters:collection(all.slice(8))}],B=[{characters:collection(all.slice(0,4))},{characters:collection(all.slice(4))}];h.frame.lines=collection(A);h.story.recompose=()=>{h.frame.lines=collection(h.chars[4].tracking===0?B:A);};const before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target);assert.throws(()=>p.preview(s({mode:'line',target:'both',autoStabilize:false,lockLines:false})),/oscillates/);assert.equal(JSON.stringify(h.doc.state),before);});
test('Add property UI keeps skew, offers only unused properties, and commits the stack',()=>{const OriginalWindow=ctx.Window;ctx.Window=function(type,title){const w=new OriginalWindow(type,title);if(title==='Add property')w.show=function(){const list=w.controls.find(c=>c.type==='dropdownlist');assert.ok(!list.items.includes('Skew'));list.selection=0;w.controls.find(c=>c.type==='button'&&c.text==='Add').onClick();return w.result;};return w;};try{const h=uiHost();interaction=root=>{const property=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Tracking');property.selection=7;const skew=h.chars.map(c=>c.skew);root.controls.find(c=>c.type==='button'&&c.text==='+ Add property').onClick();assert.equal(property.selection.index,0);assert.deepEqual(h.chars.map(c=>c.skew),skew);assert.ok(root.controls.some(c=>typeof c.text==='string'&&c.text==='Kept: Skew'));assert.ok(h.chars.some(c=>c.tracking>0));root.controls.find(c=>c.type==='button'&&c.text==='Undo addition').onClick();assert.equal(property.selection.index,7);const change=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Letters');assert.equal(change.selection.index,0);root.controls.find(c=>c.type==='button'&&c.text==='+ Add property').onClick();root.controls.find(c=>c.type==='button'&&c.text==='Apply all').onClick();};api.showDialog(h.target);assert.equal(h.doc.history.length,1);h.doc.undo();assert.ok(h.chars.every(c=>c.skew===0&&c.tracking===0));}finally{ctx.Window=OriginalWindow;}});
test('fixed sampling with Clear tracking restores the original overset baseline after frame trimming',()=>{const h=host('abc def ghi jkl'),all=h.chars;h.chars.forEach(c=>c.tracking=180);h.target.scopes=[{kind:'frame',bounds:{start:0,end:all.length-1}}];h.story.recompose=()=>{const end=h.chars[0].tracking>180?11:all.length;h.frame.lines=collection(h.chars[4].tracking===200?[{characters:collection(all.slice(0,4))},{characters:collection(all.slice(4,end))}]:[{characters:collection(all.slice(0,8))},{characters:collection(all.slice(8,end))}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'line',target:'both',min:200,max:500,clearTracking:true,autoStabilize:true,lockLines:false}));assert.equal(r.fixedSampling,true);assert.ok(h.chars.slice(r.data.bounds.end+1).every(c=>c.tracking===180));p.rollback();assert.ok(h.chars.every(c=>c.tracking===180));});
test('typing a partial numeric value does not immediately recalculate the document',()=>{const h=uiHost();interaction=root=>{const transaction=h.doc.history[0],max=root.controls.filter(c=>c.type==='edittext')[2];max.text='2';max.onChanging();assert.equal(h.doc.history[0],transaction,'Wait for typing to pause before changing the preview');root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);});

test('typing bursts coalesce into one preview 350 ms after the final keystroke',()=>{let now=0,value='2',calls=[],second=false,third=false,delay;delay=new api.PreviewDelay(350,()=>calls.push({value,at:now}),{now:()=>now,wait:ms=>now+=ms,pump(){if(now>=72&&!second){second=true;value='20';delay.request();}if(now>=168&&!third){third=true;value='200';delay.request();}},alive:()=>true});delay.request();assert.equal(calls.length,1);assert.equal(calls[0].value,'200');assert.ok(calls[0].at>=518&&calls[0].at<=530);assert.equal(delay.pending,false);});
test('Cancel during a typing delay prevents all late preview callbacks',()=>{let now=0,calls=0,delay;delay=new api.PreviewDelay(350,()=>calls++,{now:()=>now,wait:ms=>now+=ms,pump(){if(now>=96)delay.dispose();},alive:()=>true});delay.request();assert.equal(calls,0);assert.equal(delay.waiting,false);delay.request();assert.equal(calls,0);});
test('committing a field flushes the latest value immediately and only once',()=>{let now=0,calls=0,delay;delay=new api.PreviewDelay(350,()=>calls++,{now:()=>now,wait:ms=>now+=ms,pump(){if(now>=96)delay.flush();},alive:()=>true});delay.request();assert.equal(calls,1);assert.ok(now<350);delay.flush();assert.equal(calls,1);});
test('Apply uses a pending numeric value and Cancel discards it',()=>{const h=uiHost();interaction=root=>{const max=root.controls.filter(c=>c.type==='edittext')[2];max.text='275';max.onChanging();root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};api.showDialog(h.target);assert.equal(Math.max(...h.chars.map(c=>c.tracking)),275);h.doc.undo();interaction=root=>{const max=root.controls.filter(c=>c.type==='edittext')[2];max.text='275';max.onChanging();root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);assert.ok(h.chars.every(c=>c.tracking===0));});
test('native bulk bounds preserve scalar indices and fall back on unresolved columns',()=>{const good=vm.runInContext('({length:2,everyItem:function(){return{characters:{firstItem:function(){return{index:[0,5]}},lastItem:function(){return{index:[3,9]}}}}}})',ctx);assert.deepEqual(plain(api.collectionBounds(good)),[{start:0,end:3},{start:5,end:9}]);const all=[{characters:collection([{index:2},{index:6}])},{characters:collection([{index:9},{index:12}])}],bad={...collection(all),everyItem:()=>({characters:{firstItem:()=>({index:[2]}),lastItem:()=>({index:[12]})}})};assert.deepEqual(plain(api.collectionBounds(bad)),[{start:2,end:6},{start:9,end:12}]);});
test('numeric snapshots avoid resolving every character when complete bulk columns exist',()=>{const cols=vm.runInContext('[0,0,25]',ctx),story={characters:{length:3,everyItem:()=>({tracking:cols,getElements(){throw Error('Unnecessary scalar character resolution');}})}};assert.deepEqual(plain(api.takeSnapshot(story,['tracking'])),[{start:0,end:1,values:{tracking:0}},{start:2,end:2,values:{tracking:25}}]);});
test('numeric kept patches preserve previous-effect removal outside a narrower scope',()=>{const h=host('alpha beta gamma');new api.PreviewSession(h.target).commit(s({property:'skew',target:'both',min:10,max:30}));const before=h.chars.map(c=>c.skew);h.target.scopes=[{kind:'selection',bounds:{start:0,end:4}}];const p=new api.PreviewSession(h.target),cfg=s({property:'skew',min:5,max:5});p.keep(cfg);assert.ok(p.stages[0].patch);p.preview(s({max:40}));assert.ok(h.chars.slice(5).every(c=>c.skew===0));assert.ok(h.chars.slice(0,5).every(c=>c.skew===5));p.rollback();assert.deepEqual(h.chars.map(c=>c.skew),before);});
test('advanced kept effects retain the complete replay path',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'designAxes',axisName:'Weight',min:100,max:900}));assert.equal(p.stages[0].patch,null);const axes=h.chars.map(c=>c.designAxes[0]);p.preview(s({max:80}));assert.deepEqual(h.chars.map(c=>c.designAxes[0]),axes);p.rollback();});
test('a changed replay signature falls back to full reconstruction of the kept effect',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'skew',min:-10,max:20}));const before=h.chars.map(c=>c.skew);p.stages[0].replay.signature='stale';p.preview(s({max:40}));assert.deepEqual(h.chars.map(c=>c.skew),before);p.rollback();});
